"""Track 6B: LaTeX TikZ Engineering Blueprint Synthesis."""

from __future__ import annotations

from flbds.ontology.models import SapphireGraph


class TikZSchematicSynthesizer:
    """Generates publishable cross-sectional blueprints in LaTeX TikZ."""

    def synthesize(self, graph: SapphireGraph, title: str | None = None) -> str:
        doc_title = title or graph.title
        tikz_lines = [
            "% LaTeX TikZ Blueprint Generated by FLBDS v3.0",
            r"\begin{tikzpicture}[scale=0.08, >=stealth]",
            r"  % Style definitions",
            r"  \tikzstyle{keepout}=[draw=red!70!black, line width=1.5pt, fill=red!5, dashed]",
            r"  \tikzstyle{core}=[draw=blue!80!black, line width=1.5pt, fill=blue!10]",
            r"  \tikzstyle{flow}=[->, draw=cyan!80!black, line width=2pt, dashed]",
            "",
            rf"  % Title: {doc_title}",
            rf"  \node[above right] at (0, 75) {{\Large\textbf{{{doc_title}}}}};",
            rf"  \node[above right] at (0, 70) {{\small System: {graph.id}}};",
            "",
            r"  % Housing datum interface (keepout)",
            r"  \draw[keepout] (0, 50) rectangle (100, 60);",
            r"  \node at (50, 55) {\scriptsize Datum Mounting Interface (Keep-Out)};",
            "",
            r"  % Bio-inspired micro-structure core",
            r"  \draw[core] (10, 10) rectangle (90, 45);",
            r"  \node at (50, 27.5) {\textbf{Bio-Organ Topological Core}}; ",
            "",
            r"  % Flow interaction arrows",
            r"  \draw[flow] (-15, 27.5) -- (5, 27.5);",
            r"  \node[above] at (-5, 28) {\scriptsize Flow};",
            "",
            r"  % Dimensional callout",
            r"  \draw[<->] (10, 5) -- (90, 5);",
            r"  \node[below] at (50, 4) {\footnotesize $L = 480\,\mathrm{mm}$};",
            r"\end{tikzpicture}",
        ]
        return "\n".join(tikz_lines)
